function g319Metadata(PDO $p):array {
    $rows=$p->query("SELECT c.TABLE_NAME,c.COLUMN_NAME,c.ORDINAL_POSITION,c.COLUMN_TYPE,c.IS_NULLABLE,c.COLUMN_DEFAULT,c.EXTRA,c.GENERATION_EXPRESSION FROM information_schema.COLUMNS c JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=c.TABLE_SCHEMA AND t.TABLE_NAME=c.TABLE_NAME WHERE c.TABLE_SCHEMA=DATABASE() AND t.TABLE_TYPE='BASE TABLE' ORDER BY c.TABLE_NAME,c.ORDINAL_POSITION")->fetchAll();$all=[];foreach($rows as $r){$name=$r['TABLE_NAME'];unset($r['TABLE_NAME']);$all[$name][]=$r;}$out=[];foreach($all as $n=>$columns){if(array_filter($columns,fn($c)=>in_array($c['EXTRA'],['STORED GENERATED','VIRTUAL GENERATED'],true))){$out[$n]=['columns'=>$columns,'definition'=>$p->query('SHOW CREATE TABLE `'.$n.'`')->fetch()['Create Table']];}}return $out;
}
